#include <array>
#include <cstddef>
#include <cstring>
#include <iostream>
#include <string>

int main() {
    char guardadas[2][6]{"Norte", "Sur"};
    std::array<std::string, 2> propuestas{};
    const bool primeraLeida = static_cast<bool>(std::getline(std::cin, propuestas[0]));
    const bool segundaLeida = static_cast<bool>(std::getline(std::cin, propuestas[1]));
    bool aceptado = false;

    bool validas = primeraLeida && segundaLeida;
    for (std::size_t fila = 0; fila < propuestas.size(); ++fila) {
        if (propuestas[fila].size() >= 6) {
            validas = false;
        }
        for (std::size_t i = 0; i < propuestas[fila].size(); ++i) {
            if (propuestas[fila][i] == '\0') {
                validas = false;
            }
        }
    }
    if (validas) {
        char candidatas[2][6]{};
        for (std::size_t fila = 0; fila < propuestas.size(); ++fila) {
            for (std::size_t i = 0; i < propuestas[fila].size(); ++i) {
                candidatas[fila][i] = propuestas[fila][i];
            }
            candidatas[fila][propuestas[fila].size()] = '\0';
        }
        for (std::size_t fila = 0; fila < 2; ++fila) {
            for (std::size_t i = 0; i < 6; ++i) {
                guardadas[fila][i] = candidatas[fila][i];
            }
        }
        aceptado = true;
    }

    std::cout << "Guardadas\n";
    for (std::size_t fila = 0; fila < 2; ++fila) {
        std::cout << fila << ":[" << guardadas[fila] << "]:"
                  << std::strlen(guardadas[fila]) << '\n';
    }
    std::cout << "Aceptado: " << aceptado << '\n';

    return 0;
}

